<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import {LayoutGrid,ArrowLeftRight,Wallet,ArrowDownUp,Sparkles,Settings2,ChevronDown,ChevronRight,ArrowUpRight,ArrowDownLeft,ArrowUp,ArrowDown,Plus,Download,Search,CalendarDays,X,LogOut,ShieldCheck,RefreshCw,Building2,Info,Receipt,SlidersHorizontal,Check,ExternalLink,Menu,ChartNoAxesCombined,MoreHorizontal,BadgeCheck} from 'lucide-vue-next';
import TrendChart from './components/TrendChart.vue';
import ExchangeCard from './components/ExchangeCard.vue';
import AiPanel from './components/AiPanel.vue';
import {api,previewMode} from './api';
import {money,percent,currentMonth,today,monthBounds,csvCell} from './format';
import type {Account,AccountInput,Dashboard,Entry,EntryInput,Page,User,Money} from './types';

const devMode=import.meta.env.DEV;
const nav=[{id:'dashboard',label:'财务总览',icon:LayoutGrid},{id:'transactions',label:'交易流水',icon:ArrowLeftRight},{id:'accounts',label:'资金账户',icon:Wallet},{id:'exchange',label:'汇率中心',icon:ArrowDownUp},{id:'assistant',label:'AI 财务助手',icon:Sparkles}];
const route=ref('dashboard'),mobileNav=ref(false),user=ref<User|null>(null),initializing=ref(true),loading=ref(false),error=ref(''),toast=ref(''),working=ref(false);
const month=ref(currentMonth()),dashboard=ref<Dashboard|null>(null),accounts=ref<Account[]>([]),entries=ref<Page<Entry>|null>(null);
const page=ref(0),search=ref(''),kind=ref(''),accountFilter=ref(''),status=ref(''),filtersOpen=ref(false),refreshKey=ref(0);
const loginEmail=ref(import.meta.env.DEV?'demo@monef.local':''),loginPassword=ref(import.meta.env.DEV?'MonefDemo!2026':''),loginBusy=ref(false),loginError=ref('');
const selected=ref<Entry|null>(null),modal=ref(''),dialog=ref<HTMLDialogElement|null>(null),modalError=ref('');
const form=reactive<EntryInput>({accountId:'',kind:'EXPENSE',amount:'',description:'',category:'软件订阅',bookedOn:today(),clientRef:crypto.randomUUID()});
const accountForm=reactive<AccountInput>({name:'',institution:'',currency:'USD',type:'BANK',openingBalance:'0.00'});
const auditPage=ref(0),auditData=ref<Awaited<ReturnType<typeof api.audit>>|null>(null);
const categories=computed(()=>form.kind==='INCOME'?['产品收入','服务收入','其他收入']:['人力成本','市场营销','研发投入','软件订阅','办公运营','其他支出']);
const canWrite=computed(()=>user.value?.role==='ADMIN');
const title=computed(()=>nav.find(n=>n.id===route.value)?.label??'系统与审计');
const activeAccounts=computed(()=>accounts.value.filter(a=>a.active));
const totalExpenses=computed(()=>Number(dashboard.value?.expense.value??0));
const shownEntries=computed(()=>route.value==='dashboard'?entries.value?.content.slice(0,5):entries.value?.content);
const metrics=computed(()=>dashboard.value?[{label:'本月收入',en:'TOTAL REVENUE',value:money(dashboard.value.income.value),change:dashboard.value.income.change,icon:ArrowDownLeft,highlight:true,series:dashboard.value.series.map(s=>Number(s.income)),good:Number(dashboard.value.income.change)>=0},{label:'本月支出',en:'TOTAL EXPENSES',value:money(dashboard.value.expense.value),change:dashboard.value.expense.change,icon:ArrowUpRight,highlight:false,series:dashboard.value.series.map(s=>Number(s.expense)),good:Number(dashboard.value.expense.change)<=0},{label:'净现金流',en:'NET CASH FLOW',value:money(dashboard.value.netCashFlow.value),change:dashboard.value.netCashFlow.change,icon:ArrowLeftRight,highlight:false,series:dashboard.value.series.map(s=>Number(s.income)-Number(s.expense)),good:Number(dashboard.value.netCashFlow.change)>=0},{label:'收支结余率',en:'SURPLUS MARGIN',value:dashboard.value.surplusMargin===null?'—':Number(dashboard.value.surplusMargin).toFixed(1)+'%',change:null,icon:ChartNoAxesCombined,highlight:false,series:[],good:true}]:[]);
function spark(values:number[]){const min=Math.min(...values),max=Math.max(...values);return values.map((v,i)=>`${i?'L':'M'} ${i*8} ${28-(v-min)/(max-min||1)*23}`).join(' ');}
let toastTimer:ReturnType<typeof setTimeout>;function notify(message:string){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500);}
function changeRoute(id:string){route.value=id;location.hash=id;mobileNav.value=false;}
function hashChange(){const id=location.hash.slice(1);route.value=nav.some(n=>n.id===id)||id==='audit'?id:'dashboard';}
let loadId=0;
async function load(){if(!user.value)return;const id=++loadId;loading.value=true;error.value='';try{const [d,a,e]=await Promise.all([api.dashboard(month.value),api.accounts(),api.entries({...monthBounds(month.value),q:search.value||undefined,kind:kind.value||undefined,status:status.value||undefined,accountId:accountFilter.value||undefined,page:page.value,size:10})]);if(id===loadId){dashboard.value=d;accounts.value=a;entries.value=e;}if(route.value==='audit')await loadAudit();}catch(e){if(id===loadId)error.value=(e as Error).message;}finally{if(id===loadId)loading.value=false;}}
async function loadAudit(){try{auditData.value=await api.audit(auditPage.value);}catch(e){error.value=(e as Error).message;}}
async function login(){loginBusy.value=true;loginError.value='';try{user.value=await api.login(loginEmail.value,loginPassword.value);loginPassword.value='';await load();}catch(e){loginError.value=(e as Error).message;}finally{loginBusy.value=false;}}
async function logout(){try{await api.logout();user.value=null;dashboard.value=null;entries.value=null;}catch(e){notify((e as Error).message);}}
function sessionExpired(){user.value=null;}
watch([month,kind,status,accountFilter],()=>{page.value=0;void load();});watch(page,load);
watch(route,()=>{page.value=0;search.value='';kind.value='';accountFilter.value='';status.value='';void load();});
let searchTimer:ReturnType<typeof setTimeout>;watch(search,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=0;void load();},300);});
watch(()=>form.kind,()=>form.category=categories.value[0]);
watch(modal,async value=>{await nextTick();if(value){dialog.value?.showModal();}else{dialog.value?.close();}});
function closeModal(){if(!working.value){modal.value='';modalError.value='';}}
function openEntry(){Object.assign(form,{accountId:activeAccounts.value[0]?.id??'',kind:'EXPENSE',amount:'',description:'',category:'软件订阅',bookedOn:today(),clientRef:crypto.randomUUID()});modalError.value='';modal.value='entry';}
function openAccount(){Object.assign(accountForm,{name:'',institution:'',currency:'USD',type:'BANK',openingBalance:'0.00'});modalError.value='';modal.value='account';}
function viewEntry(entry:Entry){selected.value=entry;modal.value='detail';}
async function saveEntry(){working.value=true;modalError.value='';try{await api.createEntry({...form});modal.value='';notify('交易已入账，统计数据已更新');refreshKey.value++;await load();}catch(e){modalError.value=(e as Error).message;}finally{working.value=false;}}
async function saveAccount(){working.value=true;modalError.value='';try{await api.createAccount({...accountForm});modal.value='';notify('账户已创建');await load();}catch(e){modalError.value=(e as Error).message;}finally{working.value=false;}}
async function voidEntry(){if(!selected.value)return;working.value=true;modalError.value='';try{await api.voidEntry(selected.value.id);modal.value='';notify('交易已作废，审计记录已保留');refreshKey.value++;await load();}catch(e){modalError.value=(e as Error).message;}finally{working.value=false;}}
async function toggleAccount(a:Account){working.value=true;try{await api.accountStatus(a.id,!a.active);await load();notify(a.active?'账户已停用':'账户已启用');}catch(e){notify((e as Error).message);}finally{working.value=false;}}
async function exportCsv(){working.value=true;try{const all:Entry[]=[];let index=0,total=1;while(index<total){const result=await api.entries({...monthBounds(month.value),q:search.value||undefined,kind:kind.value||undefined,status:status.value||undefined,accountId:accountFilter.value||undefined,page:index,size:100});total=result.totalPages;if(total>100)throw new Error('导出最多支持 10,000 笔，请缩小筛选范围');all.push(...result.content);index++;}
 const csv=[['交易编号','日期','描述','账户','类型','分类','原币金额','币种','USD折算','入账汇率','汇率日期','汇率来源','状态'],...all.map(e=>[e.id,e.bookedOn,e.description,e.accountName,e.kind,e.category,e.amount,e.currency,e.baseAmount,e.fxRate,e.fxDate,e.fxSource,e.status])].map(row=>row.map(csvCell).join(',')).join('\r\n');
 const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`monef-transactions-${month.value}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify(`已导出 ${all.length} 笔交易`);
 }catch(e){notify((e as Error).message);}finally{working.value=false;}}
onMounted(async()=>{hashChange();window.addEventListener('hashchange',hashChange);window.addEventListener('session-expired',sessionExpired);try{user.value=await api.me();await load();}catch{user.value=null;}finally{initializing.value=false;}});
onUnmounted(()=>{window.removeEventListener('hashchange',hashChange);window.removeEventListener('session-expired',sessionExpired);clearTimeout(toastTimer);clearTimeout(searchTimer);});
</script>

<template>
 <div v-if="initializing" class="boot-screen"><span class="brand-symbol"></span><p>正在进入财务工作台…</p></div>
 <div v-else-if="!user" class="login-screen">
  <div class="login-art"><a class="brand"><span class="brand-symbol"></span>MONEF<span class="brand-period">®</span></a><div class="login-copy"><span class="eyebrow">YOUR MONEY. IN FOCUS.</span><h1>财务全貌，<br/>一目了然<span>。</span></h1><p>从每一笔交易，到下一个商业决策。<br/>让财务数据成为业务前进的力量。</p></div><div class="login-graphic"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="graphic-core"></span><div class="floating-label"><span class="live-dot"></span>Clearer insights. Smarter decisions.</div></div><span class="login-foot">企业智能财务分析与资金管理平台</span></div>
  <div class="login-form-wrap"><form class="login-form" @submit.prevent="login"><span class="eyebrow">WELCOME BACK</span><h2>欢迎回到 Monef</h2><p>登录你的企业财务工作区。</p><label>邮箱<input v-model="loginEmail" type="email" required autocomplete="username" placeholder="you@company.com"/></label><label>密码<input v-model="loginPassword" type="password" required autocomplete="current-password" placeholder="输入账户密码"/></label><p v-if="loginError" class="inline-error" role="alert">{{loginError}}</p><button class="primary full" :disabled="loginBusy">{{loginBusy?'正在登录…':'进入工作台'}}<ArrowUpRight :size="18"/></button><div v-if="devMode" class="demo-login-note"><Info :size="16"/><span>已填入本地演示账户。示例数据用于体验功能。</span></div><div class="secure-caption"><ShieldCheck :size="15"/>会话认证 · 企业数据隔离</div></form></div>
 </div>
 <div v-else class="app-shell">
  <div v-if="mobileNav" class="sidebar-shade" @click="mobileNav=false"></div>
  <aside class="sidebar" :class="{open:mobileNav}">
   <a href="#dashboard" class="brand" @click.prevent="changeRoute('dashboard')"><span class="brand-symbol"></span>MONEF<span class="brand-period">®</span></a>
   <button class="workspace-card" @click="modal='workspace'"><span class="workspace-avatar"><Building2 :size="20"/></span><span><strong>{{user.demo?'Acme Studio':'企业工作区'}}</strong><small>{{user.demo?'示例工作区':'团队工作区'}}</small></span><ChevronDown :size="14"/></button>
   <div class="nav-caption">WORKSPACE</div>
   <nav aria-label="主导航"><button v-for="item in nav" :key="item.id" :class="{active:route===item.id}" @click="changeRoute(item.id)"><component :is="item.icon" :size="19"/><span>{{item.label}}</span><span v-if="item.id==='assistant'" class="nav-ai">AI</span><span v-else-if="item.id===route" class="nav-marker"></span></button></nav>
   <div class="sidebar-insight"><div class="mini-orb"><Sparkles :size="17"/></div><h3>让每个数字更有意义</h3><p>发现趋势，理解变化。<br/>你的财务助手已就位。</p><button @click="changeRoute('assistant')">探索 Monef AI <ArrowUpRight :size="15"/></button></div>
   <div class="sidebar-bottom"><button v-if="canWrite" class="nav-bottom" :class="{active:route==='audit'}" @click="changeRoute('audit')"><Settings2 :size="18"/>系统与审计</button><button class="nav-bottom" @click="modal='help'"><Info :size="18"/>数据口径说明</button><div class="profile"><span class="avatar">{{user.name.slice(0,1)}}</span><span><strong>{{user.name}}</strong><small>{{canWrite?'工作区管理员':'财务分析员'}}</small></span><button class="icon-button" aria-label="退出登录" @click="logout"><LogOut :size="16"/></button></div></div>
  </aside>
  <div class="main-shell">
   <header class="topbar"><div class="breadcrumb"><button class="mobile-menu icon-button" aria-label="展开导航" @click="mobileNav=true"><Menu :size="20"/></button><span>工作台</span><ChevronRight :size="13"/><strong>{{title}}</strong></div><div class="topbar-right"><span class="environment-tag"><span class="live-dot"></span>{{previewMode?'交互演示':user.demo?'本地演示':'企业工作区'}}</span><span class="topbar-divider"></span><span class="topbar-currency">USD <ChevronDown :size="12"/></span><button class="avatar small" aria-label="账户信息" @click="modal='workspace'">{{user.name.slice(0,1)}}</button></div></header>
   <main>
    <div class="page-heading"><div><span class="eyebrow">{{route==='dashboard'?'YOUR BUSINESS, AT A GLANCE.':route==='assistant'?'INTELLIGENCE, GROUNDED IN YOUR DATA.':'EVERY DETAIL MATTERS.'}}</span><h1>{{title}}<span v-if="route==='dashboard'" class="title-dot">.</span></h1><p>{{route==='dashboard'?'欢迎回来，'+user.name+'。每一笔流动，都心中有数。':route==='transactions'?'追踪每一笔收支，让业务的来龙去脉清晰可见。':route==='accounts'?'统一查看账户与资金余额，掌握企业资金分布。':route==='exchange'?'跨越币种，保持清晰。查询、换算与追溯汇率。':route==='assistant'?'从财务问题出发，让账本提供有依据的答案。':'关键操作可追溯，企业数据有边界。'}}</p></div>
     <div class="page-actions"><label v-if="!['accounts','exchange','audit'].includes(route)" class="month-control"><CalendarDays :size="16"/><input type="month" v-model="month" min="2000-01" :max="currentMonth()" aria-label="统计月份"/></label><button v-if="['dashboard','transactions'].includes(route)" class="secondary" aria-label="导出交易 CSV" :disabled="working" @click="exportCsv"><Download :size="16"/><span>导出</span></button><button v-if="canWrite&&['dashboard','transactions'].includes(route)" class="primary" @click="openEntry"><Plus :size="17"/>新增交易</button><button v-if="canWrite&&route==='accounts'" class="primary" @click="openAccount"><Plus :size="17"/>新增账户</button></div>
    </div>
    <div v-if="previewMode" class="preview-banner"><Info :size="14"/><span>交互演示使用示例数据，修改仅保存在当前浏览器。企业部署版本使用服务端数据。</span></div>
    <div v-if="error" class="error-banner" role="alert"><Info :size="18"/><span>{{error}}</span><button @click="load">重新加载</button></div>
    <div v-if="loading&&!dashboard" class="skeleton-grid"><div v-for="n in 4" :key="n" class="skeleton"></div></div>
    <template v-if="route==='dashboard'&&dashboard">
     <section class="kpi-grid" aria-label="本月财务指标"><article v-for="metric in metrics" :key="metric.label" class="kpi-card" :class="{highlight:metric.highlight}"><div class="kpi-top"><span class="kpi-icon"><component :is="metric.icon" :size="17"/></span><span>{{metric.label}}</span><ArrowUpRight :size="14" class="muted"/></div><div class="kpi-value">{{metric.value}}</div><div class="kpi-bottom"><div v-if="metric.change!==null"><span class="change-badge" :class="{negative:!metric.good}"><ArrowUp v-if="Number(metric.change)>=0" :size="11"/><ArrowDown v-else :size="11"/>{{percent(metric.change)}}</span><small>较上月</small></div><small v-else>{{metric.label==='收支结余率'?'（收入 − 支出）/ 收入':'上月无可比数据'}}</small><svg v-if="metric.series.length" class="sparkline" viewBox="0 0 90 32" aria-hidden="true"><path :d="spark(metric.series)" fill="none" :stroke="metric.highlight?'#cec3ff':'#85818f'" stroke-width="1.8" stroke-linecap="round"/></svg><span v-else class="kpi-health"><BadgeCheck :size="19"/></span></div></article></section>
     <div class="dashboard-grid"><div class="dashboard-main"><TrendChart :data="dashboard"/><section class="panel expense-panel"><div class="panel-heading"><div><span class="eyebrow">WHERE YOUR MONEY GOES</span><h2>支出构成</h2></div><span class="panel-total">{{money(dashboard.expense.value)}}<small>本月总支出</small></span></div><div class="expense-visual" v-if="dashboard.categories.length"><div v-for="(c,i) in dashboard.categories" :key="c.category" :style="{flex:Number(c.amount),background:['#8a76f5','#5f53a8','#41414b','#a6f2b0','#76737f','#55545e'][i%6]}" :title="`${c.category}: ${money(c.amount)}`"></div></div><div class="category-grid"><div v-for="(c,i) in dashboard.categories" :key="c.category" class="category-item"><i class="dot" :style="{background:['#8a76f5','#5f53a8','#41414b','#a6f2b0','#76737f','#55545e'][i%6]}"></i><span>{{c.category}}<small>{{c.count}} 笔交易</small></span><strong>{{money(c.amount)}}<small>{{totalExpenses?(Number(c.amount)/totalExpenses*100).toFixed(1):0}}%</small></strong></div></div><p v-if="!dashboard.categories.length" class="empty">本月暂无已入账支出。</p></section></div><div class="dashboard-side"><ExchangeCard/><AiPanel :month="month" @open="changeRoute('assistant')"/></div></div>
    </template>
    <section v-if="['dashboard','transactions'].includes(route)&&dashboard" class="panel transactions-panel">
     <div class="panel-heading"><div><span class="eyebrow">TRANSACTION ACTIVITY</span><h2>{{route==='dashboard'?'最近交易':'交易明细'}} <span class="count-badge">{{entries?.totalElements??0}}</span></h2></div><button v-if="route==='dashboard'" class="text-button" @click="changeRoute('transactions')">查看全部 <ArrowUpRight :size="15"/></button><div v-else class="table-tools"><div class="search-field"><Search :size="16"/><input v-model="search" placeholder="搜索交易描述…" aria-label="搜索交易" maxlength="100"/><button v-if="search" aria-label="清空搜索" @click="search=''"><X :size="14"/></button></div><button class="secondary" :class="{selected:filtersOpen}" @click="filtersOpen=!filtersOpen"><SlidersHorizontal :size="15"/>筛选</button></div></div>
     <div v-if="route==='transactions'" class="transaction-tabs"><button :class="{active:kind===''}" @click="kind=''">全部交易</button><button :class="{active:kind==='INCOME'}" @click="kind='INCOME'">收入</button><button :class="{active:kind==='EXPENSE'}" @click="kind='EXPENSE'">支出</button><span class="tab-end">{{month}} · 原币金额</span></div>
     <div v-if="filtersOpen&&route==='transactions'" class="filter-row"><label>账户<select v-model="accountFilter"><option value="">全部账户</option><option v-for="a in accounts" :key="a.id" :value="a.id">{{a.name}}</option></select></label><label>状态<select v-model="status"><option value="">全部状态</option><option value="POSTED">已入账</option><option value="VOID">已作废</option></select></label><button class="text-button" @click="accountFilter='';status='';search='';kind=''">重置筛选</button></div>
     <div class="table-scroll" :aria-busy="loading"><table class="transaction-table"><thead><tr><th>交易名称</th><th>分类</th><th>日期</th><th>状态</th><th class="align-right">金额</th><th><span class="sr-only">详情</span></th></tr></thead><tbody><tr v-for="entry in shownEntries" :key="entry.id"><td><button class="transaction-name" @click="viewEntry(entry)"><span class="merchant-icon" :class="entry.kind==='INCOME'?'incoming':'outgoing'"><ArrowDownLeft v-if="entry.kind==='INCOME'" :size="17"/><ArrowUpRight v-else :size="17"/></span><span><strong>{{entry.description}}</strong><small>{{entry.accountName}}</small></span></button></td><td><span class="category-chip">{{entry.category}}</span></td><td>{{entry.bookedOn}}</td><td><span class="status-pill" :class="{void:entry.status==='VOID'}"><i></i>{{entry.status==='POSTED'?'已入账':'已作废'}}</span></td><td class="align-right numeric" :class="{income:entry.kind==='INCOME'}">{{entry.kind==='INCOME'?'+':'−'}}{{money(entry.amount,entry.currency,2)}}<small class="currency-label">{{entry.currency}}</small></td><td><button class="icon-button" aria-label="查看交易详情" @click="viewEntry(entry)"><ChevronRight :size="16"/></button></td></tr></tbody></table></div>
     <div v-if="!shownEntries?.length" class="empty-state"><Receipt :size="30"/><h3>这里还没有交易</h3><p>调整筛选条件，或记下第一笔收支。</p><button v-if="canWrite" class="secondary" @click="openEntry"><Plus :size="15"/>新增交易</button></div>
     <div class="table-footer"><span>{{route==='dashboard'?'最近 5 笔交易':'共 '+(entries?.totalElements??0)+' 笔交易'}}<span class="footer-dot">·</span>所有金额保留原币种</span><div v-if="route==='transactions'" class="pagination"><button :disabled="page===0||loading" @click="page--">上一页</button><span>{{page+1}} / {{Math.max(1,entries?.totalPages??1)}}</span><button :disabled="page+1>=(entries?.totalPages??0)||loading" @click="page++">下一页</button></div><button v-else class="icon-button" aria-label="刷新财务数据" @click="load"><RefreshCw :size="14" :class="{spin:loading}"/></button></div>
    </section>
    <template v-if="route==='accounts'"><div class="accounts-grid"><article v-for="(a,i) in accounts" :key="a.id" class="account-card" :class="{inactive:!a.active}"><div class="account-top"><span class="bank-icon"><Building2 :size="23"/></span><span class="account-currency">{{a.currency}} <span class="live-dot" v-if="a.active"></span></span></div><span class="account-label">{{a.name}}</span><h2>{{money(a.balance,a.currency,2)}}</h2><span class="account-balance-label">账面余额</span><div class="account-decoration" :class="'decoration-'+i"></div><div class="account-bottom"><span>{{a.institution}}<small>{{a.active?'账户使用中':'已停用'}}</small></span><button v-if="canWrite" class="account-toggle" :disabled="working" @click="toggleAccount(a)">{{a.active?'停用':'启用'}}</button></div></article><button v-if="canWrite" class="add-account" @click="openAccount"><span><Plus :size="25"/></span><strong>添加资金账户</strong><small>让所有资金汇聚于此</small></button></div><div class="info-callout"><Info :size="18"/><p>余额 = 期初余额 + 已入账收入 − 已入账支出。不同币种独立展示；停用账户保留历史交易。</p></div></template>
    <div v-if="route==='exchange'" class="exchange-page"><ExchangeCard expanded/></div>
    <AiPanel v-if="route==='assistant'" :month="month" :key="refreshKey" expanded/>
    <template v-if="route==='audit'"><div class="system-cards"><div class="panel"><ShieldCheck :size="24"/><h3>企业隔离</h3><p>租户由登录身份决定，所有账本查询均在当前企业范围内。</p></div><div class="panel"><Receipt :size="24"/><h3>流水可追溯</h3><p>交易仅允许作废，保留原始金额、汇率快照和操作记录。</p></div><div class="panel"><Sparkles :size="24"/><h3>受限 AI 工具</h3><p>只读查询，固定企业与月份，不执行 SQL 或资金操作。</p></div></div><section class="panel"><div class="panel-heading"><div><span class="eyebrow">ACTIVITY LOG</span><h2>操作审计</h2></div><button class="icon-button" aria-label="刷新审计" @click="loadAudit"><RefreshCw :size="16"/></button></div><div class="table-scroll"><table><thead><tr><th>时间</th><th>操作人</th><th>事件</th><th>详情</th></tr></thead><tbody><tr v-for="a in auditData?.content" :key="a.id"><td>{{new Date(a.createdAt).toLocaleString('zh-CN')}}</td><td>{{a.actor}}</td><td>{{a.action}}</td><td>{{a.detail}}</td></tr></tbody></table></div><p v-if="!auditData?.content.length" class="empty">首次创建账户、记账或分析后，这里会显示操作记录。</p><div class="table-footer"><span>共 {{auditData?.totalElements??0}} 条记录</span><div class="pagination"><button :disabled="auditPage===0" @click="auditPage--;loadAudit()">上一页</button><span>{{auditPage+1}} / {{Math.max(1,auditData?.totalPages??1)}}</span><button :disabled="auditPage+1>=(auditData?.totalPages??0)" @click="auditPage++;loadAudit()">下一页</button></div></div></section></template>
    <footer class="page-footer"><span><span class="brand-symbol tiny"></span>Monef<span>让资金管理，更进一步。</span></span><span>{{dashboard?'更新于 '+new Date(dashboard.generatedAt).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}):'企业智能财务工作台'}}<span class="footer-dot">·</span><button @click="modal='help'">数据口径</button></span></footer>
   </main>
  </div>
 </div>
 <dialog ref="dialog" @cancel.prevent="closeModal" @click="(event)=>{if(event.target===dialog)closeModal()}">
  <div class="modal-inner"><button class="modal-close icon-button" aria-label="关闭弹窗" :disabled="working" @click="closeModal"><X :size="20"/></button>
   <template v-if="modal==='entry'"><span class="eyebrow">NEW TRANSACTION</span><h2>记录一笔交易</h2><p class="modal-description">金额使用所选账户币种，入账时保存汇率快照。</p><form @submit.prevent="saveEntry"><div class="form-segments"><button type="button" :class="{active:form.kind==='EXPENSE'}" @click="form.kind='EXPENSE'"><ArrowUpRight :size="17"/>支出</button><button type="button" :class="{active:form.kind==='INCOME'}" @click="form.kind='INCOME'"><ArrowDownLeft :size="17"/>收入</button></div><label>交易描述<input v-model="form.description" required maxlength="200" placeholder="例如：本月软件订阅" autofocus/></label><div class="form-grid"><label>资金账户<select v-model="form.accountId" required><option value="" disabled>请选择账户</option><option v-for="a in activeAccounts" :key="a.id" :value="a.id">{{a.name}} · {{a.currency}}</option></select></label><label>金额<input v-model="form.amount" required type="number" min="0.01" max="9999999999999.99" step="0.01" placeholder="0.00"/></label><label>交易分类<select v-model="form.category" required><option v-for="c in categories" :key="c">{{c}}</option></select></label><label>记账日期<input v-model="form.bookedOn" type="date" min="2000-01-01" :max="today()" required/></label></div><p v-if="!activeAccounts.length" class="inline-error">请先创建或启用资金账户。</p><p v-if="modalError" class="inline-error" role="alert">{{modalError}}</p><div class="modal-actions"><button class="secondary" type="button" :disabled="working" @click="closeModal">取消</button><button class="primary" :disabled="working||!activeAccounts.length">{{working?'正在保存…':'确认入账'}}<Check :size="16"/></button></div></form></template>
   <template v-if="modal==='account'"><span class="eyebrow">NEW ACCOUNT</span><h2>添加资金账户</h2><p class="modal-description">建立账户档案，记录期初余额与后续收支。</p><form @submit.prevent="saveAccount"><label>账户名称<input v-model="accountForm.name" required maxlength="100" placeholder="例如：企业运营账户" autofocus/></label><label>所属机构<input v-model="accountForm.institution" required maxlength="100" placeholder="例如：招商银行 ···· 3826"/></label><div class="form-grid"><label>币种<select v-model="accountForm.currency"><option v-for="c in ['USD','EUR','GBP','CNY','JPY','SGD','HKD','AUD','CAD','CHF']" :key="c">{{c}}</option></select></label><label>账户类型<select v-model="accountForm.type"><option value="BANK">银行账户</option><option value="WALLET">电子钱包</option><option value="CASH">现金账户</option></select></label></div><label>期初余额<input v-model="accountForm.openingBalance" type="number" min="0" max="9999999999999.99" step="0.01" required/></label><p v-if="modalError" class="inline-error" role="alert">{{modalError}}</p><div class="modal-actions"><button class="secondary" type="button" :disabled="working" @click="closeModal">取消</button><button class="primary" :disabled="working">{{working?'正在保存…':'创建账户'}}</button></div></form></template>
   <template v-if="modal==='detail'&&selected"><span class="eyebrow">TRANSACTION DETAILS</span><h2>{{selected.description}}</h2><div class="detail-amount" :class="{income:selected.kind==='INCOME'}">{{selected.kind==='INCOME'?'+':'−'}}{{money(selected.amount,selected.currency,2)}}<small>{{selected.currency}}</small></div><dl class="detail-list"><div><dt>资金账户</dt><dd>{{selected.accountName}}</dd></div><div><dt>分类 / 状态</dt><dd>{{selected.category}} · {{selected.status==='POSTED'?'已入账':'已作废'}}</dd></div><div><dt>记账日期</dt><dd>{{selected.bookedOn}}</dd></div><div><dt>USD 折算金额</dt><dd>{{money(selected.baseAmount,'USD',2)}}</dd></div><div><dt>入账汇率</dt><dd>1 {{selected.currency}} = {{Number(selected.fxRate).toFixed(6)}} USD</dd></div><div><dt>汇率日期 / 来源</dt><dd>{{selected.fxDate}} · {{selected.fxSource}}</dd></div><div><dt>交易编号</dt><dd class="mono">{{selected.id}}</dd></div></dl><div class="modal-actions"><button class="secondary" @click="closeModal">关闭</button><button v-if="canWrite&&selected.status==='POSTED'" class="danger-button" @click="modal='void'">作废交易</button></div></template>
   <template v-if="modal==='void'&&selected"><span class="eyebrow">VOID TRANSACTION</span><h2>作废这笔交易？</h2><p class="modal-description">“{{selected.description}}”将不再计入账户余额及财务统计。原始流水和审计记录仍会保留。</p><p v-if="modalError" class="inline-error" role="alert">{{modalError}}</p><div class="modal-actions"><button class="secondary" :disabled="working" @click="modal='detail'">返回</button><button class="danger-button" :disabled="working" @click="voidEntry">{{working?'处理中…':'确认作废'}}</button></div></template>
   <template v-if="modal==='workspace'"><span class="eyebrow">YOUR WORKSPACE</span><h2>{{user?.demo?'Acme Studio':'企业工作区'}}</h2><dl class="detail-list"><div><dt>登录账户</dt><dd>{{user?.email}}</dd></div><div><dt>角色</dt><dd>{{canWrite?'管理员':'分析员'}}</dd></div><div><dt>企业编号</dt><dd>{{user?.tenantId}}</dd></div><div><dt>当前模式</dt><dd>{{previewMode?'浏览器交互演示':user?.demo?'Java 后端演示环境':'企业运行环境'}}</dd></div></dl><p class="modal-description">{{previewMode?'数据只保存在当前浏览器，不代表真实企业的财务情况。':'企业身份由服务端登录会话确定，不能通过客户端切换。'}}</p><button class="secondary full" @click="closeModal">知道了</button></template>
   <template v-if="modal==='help'"><span class="eyebrow">ABOUT YOUR NUMBERS</span><h2>每个数字，都有依据</h2><div class="help-copy"><h3>统一统计口径</h3><p>仪表盘使用 USD，按每笔交易入账时的汇率快照汇总。账户余额保留原币种。</p><h3>净现金流与结余率</h3><p>净现金流 = 收入 − 支出；结余率 = 净现金流 / 收入。此处为收付口径，不等同于权责发生制净利润。收入为零时，结余率为空。</p><h3>环比与日期</h3><p>环比与上一自然月比较；上月为零时不计算百分比。本月尚未结束时，比较的是本月至今与完整上月。日期以 UTC 为准。</p><h3>汇率与 AI</h3><p>演示模式使用明确标注的固定汇率。正式环境接入 Frankfurter 日参考汇率，并保存来源、日期和缓存状态。AI 仅可查询当前企业所选月份的数据。</p></div><a class="text-button reference-link" href="https://dribbble.com/shots/27389006-UI-elements-for-Monef-Corporate-Finance-Dashboard" target="_blank" rel="noopener noreferrer">设计参考 · One Collective Design <ExternalLink :size="14"/></a></template>
  </div>
 </dialog>
 <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Check :size="16"/>{{toast}}</div></Transition>
</template>
